# -*- coding: utf-8 -*-
# Сверка с ответами учебника Макарычев 9 (углублённый), часть 1 (расхождения 0–59): пересчитано вручную + SymPy (check_mk1.py),
# условия сверены со сканом (OCR mistral_2301917bac643c6d).
KB = "ключ неверен (сверка с ответом учебника Макарычев 9 и пересчёт вручную): "
SRC = "сверка с ответами учебника Макарычев 9 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G9_TB_УПК_788", r"$80$", "d = (110 − 150)/10 = −4, a₁ = 158; Sₙ = n(320 − 4n)/2 = 0 ⇒ n = 80 (было 79)", dadd=OLD(r"$79$", "ошибка на единицу"))
K("G9_TB_30_611", r"$2$, $5$, $8$", "5 − d, 5, 5 + d; (6 − d)(9 + d) = 36 ⇒ d = 3 (d = −6 даёт отрицательное число): 2, 5, 8 (было 3, 5, 7: 4, 6, 11 — не геометрическая прогрессия)", dadd=OLD(r"$3, 5, 7$", "не проверено условие"))
K("G9_TB_15_250", r"$\dfrac{12}{18}$", "x/(x + 6) − (x − 2)/(x + 8) = 1/6 ⇒ x² − 10x − 24 = 0 ⇒ x = 12: 12/18 − 10/20 = 1/6 (было 5/11)")
K("G9_TB_14_237_2", r"$-0{,}5$", "после умножения на a(a − 1)(a + 1): 2a² − a − 1 = 0 ⇒ a = 1 (не входит в ОДЗ) или a = −0,5 (было 1/3)")
K("G9_TB_УПК_691_2", r"$1$", "x² − x − 5 = √5 и x − 1 = √5 при x = √5 + 1 ⇒ значение 1 (было √5 − 1)")
P["G9_TB_УПК_692_2"] = {"qrep": (r"- 0$, $25^{-2} \cdot 16", r"- 0{,}25^{-2} \cdot 16"), "k": r"$-262\dfrac{5}{8}$", "src": SRC,
  "why": KB + "9/4 − 9 + 1/8 − 0,25⁻²·16 = 9/4 − 9 + 1/8 − 256 = −262 5/8 (было −262 7/8); десятичная дробь 0,25 в условии была разорвана («0$, $25»)"}
K("G9_TB_20_390_2", r"$(3; -5)$, $(5; -8)$", "y = (−1 − 3x)/2 ⇒ x² − 8x + 15 = 0 ⇒ x = 3, 5 (было (−5; 7), (2; −3,5) — не решения)")
K("G9_TB_20_394.2", r"$(-4; 0)$", "вычитание уравнений: −4x + 4 = 20 ⇒ x = −4, y = 0 — окружности касаются (было (−3; ±√7))")
K("G9_TB_14_233_2", r"$a = 0$", "при a = −2 знаменатель a³ + a + 10 = 0, поэтому остаётся только a = 0 (было 0 и −2)")
K("G9_TB_13_216", r"$17$ и $12$ или $-12$ и $-17$", "x² + xy + y² = 637 при x = y + 5 ⇒ y² + 5y − 204 = 0 ⇒ y = 12 или −17 (было 14 и 9: 14³ − 9³ = 2015)")
K("G9_TB_ЗПТ_866", r"$2 \leq n \leq 20$", "n — номер члена (натуральное): n² − n − 2 ≥ 0 ⇒ n ≥ 2, n² − n − 380 ≤ 0 ⇒ n ≤ 20 (было перечисление с отрицательными n)")
P["G9_TB_22_426"] = {"q": "От вершины прямого угла по его сторонам начинают одновременно двигаться два тела. Через $15$ с расстояние между ними стало равно $3$ м. С какой скоростью двигалось каждое тело, если известно, что первое прошло за $6$ с такое же расстояние, какое второе прошло за $8$ с?",
  "k": r"$0{,}16$ м/с и $0{,}12$ м/с", "src": SRC,
  "why": "условие было оборвано на «расстояние между ними» (конец восстановлен по учебнику Макарычев 9, № 426), ключ «недостаточно данных» заменён: 6v₁ = 8v₂, (15v₁)² + (15v₂)² = 9 ⇒ v₁ = 0,16, v₂ = 0,12; прежние варианты были выражениями для обрывка условия и заменены",
  "dnew": {0: (r"$0{,}12$ м/с и $0{,}16$ м/с", "скорости перепутаны: быстрее движется первое тело"), 1: (r"$0{,}24$ м/с и $0{,}18$ м/с", "расстояние через 15 с получится 4,5 м, а не 3 м"),
           2: (r"$0{,}8$ м/с и $0{,}6$ м/с", "не учтено время 15 с")}}
K("G9_TB_21_405_3", r"$2$", "x² + (4x + 5)² = 5 ⇒ 17x² + 40x + 20 = 0, D = 240 > 0 — две общие точки (было 1)", dadd=OLD(r"$1$", "неверно вычислен дискриминант"))
K("G9_TB_20_392_3", r"$(8; 6)$, $(-7; -9)$", "вычитание: x − y = 2 ⇒ y² + 3y − 54 = 0 ⇒ (8; 6), (−7; −9) (было (7; 7), (−8; −8)); вариант «(−7; −9), (8; 6)» равен ответу — закрыт",
  drop=[2], dadd=OLD(r"$(7;7), (-8;-8)$", "не решения системы"))
K("G9_TB_20_386_1", r"$(12; 13)$, $(-14; -13)$", "y = x + 1 ⇒ x² + 2x − 168 = 0 ⇒ x = 12 или −14 (было (−15; −14))")
K("G9_TB_16_258", r"$16$", "течение c: 60/c + 5 = 60/(10 − c) ⇒ c² + 14c − 120 = 0 ⇒ c = 6, скорость по течению 16 км/ч (было 15)")
K("G9_TB_15_256", r"урожайность первого участка $10$ ц/га; урожайность второго участка $15$ ц/га", "площадь первого x га: 90/(x − 2) − 80/x = 5 ⇒ x = 8 ⇒ 10 и 15 ц/га (было 20 и 25)",
  dadd=OLD(r"урожайность первого участка $20$ ц/га; урожайность второго участка $25$ ц/га", "площади не отличаются на 2 га"))
K("G9_TB_15_255", r"$2$ ч или $2{,}5$ ч", "30/v + 1/2 = 45/(v + 3) ⇒ v² − 27v + 180 = 0 ⇒ v = 12 или 15, время 2,5 ч или 2 ч (в ключе был только один ответ)")
K("G9_TB_15_253", r"$1{,}5$", "60/(v − 10) − 60/v = 0,3 ⇒ v² − 10v − 2000 = 0 ⇒ v = 50, обратный путь 60/40 = 1,5 ч (было 1,8)", dadd=OLD(r"$1{,}8$", "ошибка в вычислениях"))
K("G9_TB_15_249", r"$x = 12$; $y = 6$", "x/y + 4y/x = 4 ⇔ (x − 2y)² = 0 ⇒ x = 2y = y + 6 ⇒ 12 и 6 (было 8 и 2)", dadd=OLD(r"$x = 8; y = 2$", "не проверено условие"))
K("G9_TB_11_160", r"$n = 5$, $(-1, 13)$", "x² + 2x + 6 − n = 0, D = 0 ⇒ n = 5, x = −1, y = 13 (было n = 2)", dadd=OLD(r"$n = 2$, $(-1, 13)$", "неверное n"))
